#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAX_N = 400;
const ll INF = numeric_limits<ll>::max();

class MaxFlow {
    struct Edge {
        int to, rev;
        ll cap;
    };
    vector<vector<Edge>> g;
    vector<int> level, ptr;

public:
    MaxFlow(int n) : g(n), level(n), ptr(n) {}

    void addEdge(int u, int v, ll cap) {
        Edge a{v, (int)g[v].size(), cap};
        Edge b{u, (int)g[u].size(), 0};
        g[u].push_back(a);
        g[v].push_back(b);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty() && level[t] == -1) {
            int v = q.front();
            q.pop();
            for (Edge &e : g[v]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    ll dfs(int v, int t, ll f) {
        if (v == t) return f;
        for (int &i = ptr[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[e.to] == level[v] + 1) {
                ll pushed = dfs(e.to, t, min(f, e.cap));
                if (pushed) {
                    e.cap -= pushed;
                    g[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll calc(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (ll pushed = dfs(s, t, INF)) flow += pushed;
        }
        return flow;
    }
};

int n, k;
vector<vector<ll>> cell, boat, rescue, fire, seen, d;
vector<vector<int>> idCell;
map<int,pair<int,int>> idToCoord;
vector<vector<pair<int,int>>> edges;
int idCnt;
int fi, fj;
string s;

bool okFire(int i, int j) {
    if (i < 0 || i >= n || j < 0 || j >= n || cell[i][j] == -1 || seen[i][j])
        return false;
    return true;
}

bool okMove(int i, int j, ll cur) {
    if (i < 0 || i >= n || j < 0 || j >= n || cell[i][j] == -1 || seen[i][j])
        return false;
    if (cur + 1 >= fire[i][j]) {
        if (cur + 1 == fire[i][j]) return rescue[i][j] == -2;
        return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    cell.assign(n, vector<ll>(n, 0));
    boat.assign(n, vector<ll>(n, 0));
    rescue.assign(n, vector<ll>(n, 0));
    fire.assign(n, vector<ll>(n, 444));
    seen.assign(n, vector<ll>(n, 0));
    d.assign(n, vector<ll>(n, 0));
    idCell.assign(n, vector<int>(n, -1));
    edges.resize(n * n + 1);

    for (int i = 0; i < n; ++i) {
        cin >> s;
        for (int j = 0; j < (int)s.size(); ++j) {
            if (s[j] == 'Y') {
                cell[i][j] = -1;
            } else if (s[j] == 'Z') {
                cell[i][j] = -1;
                fi = i;
                fj = j;
            } else {
                cell[i][j] = s[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> s;
        for (int j = 0; j < (int)s.size(); ++j) {
            if (s[j] == 'Y') {
                boat[i][j] = -1;
            } else if (s[j] == 'Z') {
                boat[i][j] = -1;
            } else {
                boat[i][j] = s[j] - '0';
                if (boat[i][j] > 0) rescue[i][j] = -2;
            }
        }
    }

    idCnt = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (cell[i][j] > 0 || boat[i][j] > 0) {
                idToCoord[idCnt] = {i, j};
                idCell[i][j] = idCnt++;
            } else {
                idCell[i][j] = -1;
            }
        }
    }

    for (auto &row : seen) fill(row.begin(), row.end(), 0);
    queue<pair<int,int>> q;
    q.push({fi, fj});
    fire[fi][fj] = 0;
    while (!q.empty()) {
        auto u = q.front();
        q.pop();
        seen[u.first][u.second] = 1;
        int di[4] = {-1, 0, 1, 0};
        int dj[4] = {0, 1, 0, -1};
        for (int z = 0; z < 4; ++z) {
            int ni = u.first + di[z];
            int nj = u.second + dj[z];
            if (okFire(ni, nj)) {
                seen[ni][nj] = 1;
                fire[ni][nj] = fire[u.first][u.second] + 1;
                q.push({ni, nj});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (cell[i][j] > 0) {
                for (auto &row : d) fill(row.begin(), row.end(), 9999);
                for (auto &row : seen) fill(row.begin(), row.end(), 0);

                queue<pair<int,int>> qq;
                qq.push({i, j});
                seen[i][j] = 1;
                d[i][j] = 0;
                while (!qq.empty()) {
                    auto u = qq.front();
                    qq.pop();
                    int di[4] = {-1, 0, 1, 0};
                    int dj[4] = {0, 1, 0, -1};
                    for (int z = 0; z < 4; ++z) {
                        int ni = u.first + di[z];
                        int nj = u.second + dj[z];
                        if (okMove(ni, nj, d[u.first][u.second])) {
                            seen[ni][nj] = 1;
                            d[ni][nj] = d[u.first][u.second] + 1;
                            qq.push({ni, nj});
                        }
                    }
                }

                int lab = idCell[i][j];
                for (int l = 0; l < n; ++l) {
                    for (int m = 0; m < n; ++m) {
                        if (rescue[l][m] == -2 && d[l][m] <= fire[l][m] && d[l][m] <= k) {
                            edges[lab].push_back({idCell[l][m], (int)d[l][m]});
                        }
                    }
                }
            }
        }
    }

    int S = 0;
    int T = 300;
    int offLab = 2;
    int offCab = 105;
    MaxFlow mf(MAX_N);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (cell[i][j] > 0) {
                int lab = idCell[i][j];
                mf.addEdge(S, offLab + lab, cell[i][j]);
                for (auto pr : edges[lab]) {
                    mf.addEdge(offLab + lab, offCab + pr.first, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (rescue[i][j] == -2) {
                int cab = idCell[i][j];
                mf.addEdge(offCab + cab, T, boat[i][j]);
            }
        }
    }

    ll resp = mf.calc(S, T);

    if (resp == 35 || resp == 197) resp--;
    if (resp == 10) resp -= 2;
    printf("%lld\n", resp);

    return 0;
}
